    'start': 'r0',
    'accept': {'r0'},
    'delta': {('r0', '0'): 'r0', ('r0', '1'): 'r1', ('r1', '0'): 'r2',
              ('r1', '1'): 'r0', ('r2', '0'): 'r1', ('r2', '1'): 'r2'},
}
IDENT = {
    'start': 's',
    'accept': {'id'},
    'delta': {('s', 'a'): 'id', ('s', 'b'): 'id', ('id', 'a'): 'id', ('id', 'b'): 'id', ('id', '0'): 'id', ('id', '1'): 'id'},
}

def run_dfa(dfa, s):
    # start at the initial state
    current_state = dfa['start']
    # for every symbol in the string
    for ch in s:
        # look up the next state
        key = (current_state, ch)
        if key in dfa['delta']:
            current_state = dfa['delta'][key]
        else:
            # no transition, stuck
            return None
    return current_state

def accepts(dfa, s):
    final_state = run_dfa(dfa, s)
    if final_state is None:
        return False
    if final_state in dfa['accept']:
        return True
    else:
        return False

print(accepts(DIV3, '110'))

